import re


def parse(text):
    """Parse INI-formatted text and return a dict mapping section names
    to dicts of key/value pairs."""
    if not text or not text.strip():
        return {}

    result = {}
    current_section = 'DEFAULT'

    for line in text.splitlines():
        stripped = line.strip()

        # Skip blank lines
        if not stripped:
            continue

        # Skip full-line comments
        if stripped.startswith('#') or stripped.startswith(';'):
            continue

        # Section header
        if stripped.startswith('['):
            bracket_end = stripped.find(']')
            if bracket_end == -1:
                raise ValueError(
                    f"Section without closing bracket: {stripped!r}"
                )
            section_name = stripped[1:bracket_end]
            if section_name not in result:
                result[section_name] = {}
            current_section = section_name
            continue

        # Key = value
        eq_pos = stripped.find('=')
        if eq_pos == -1:
            raise ValueError(f"Invalid line: {stripped!r}")

        key = stripped[:eq_pos].strip()
        raw_value = stripped[eq_pos + 1:]

        value = _parse_value(raw_value)

        if current_section not in result:
            result[current_section] = {}
        result[current_section][key] = value

    return result


def _parse_value(raw):
    """Parse a raw value string: handle quotes, trailing comments, type coercion."""
    stripped = raw.strip()
    if not stripped:
        return ''

    # Double-quoted value
    if stripped[0] == '"':
        end = stripped.find('"', 1)
        if end != -1:
            return stripped[1:end]
        # No closing quote — fall through to unquoted handling

    # Single-quoted value
    if stripped[0] == "'":
        end = stripped.find("'", 1)
        if end != -1:
            return stripped[1:end]
        # No closing quote — fall through to unquoted handling

    # Unquoted value: strip trailing comments (' #' or ' ;')
    # Search in the *raw* (pre-strip) text so that e.g. " ;comment" right
    # after '=' is correctly recognised as a trailing comment.
    idx_hash = raw.find(' #')
    idx_semi = raw.find(' ;')

    cuts = [i for i in (idx_hash, idx_semi) if i != -1]
    if cuts:
        raw = raw[:min(cuts)]

    value = raw.strip()
    return _convert_value(value)


_INT_RE = re.compile(r'^[+-]?\d+$')


def _convert_value(value):
    """Coerce an unquoted string to bool / int / str."""
    if value.lower() == 'true':
        return True
    if value.lower() == 'false':
        return False
    if _INT_RE.match(value):
        return int(value)
    return value

